          ]
        },
        {
          "stage": "price",
          "focus": "价格与限时优惠",
          "sentences": [
            {
              "display_text": "原价 178 新台币，限时下杀 107 新台币。",
              "spoken_text": "原价一百七十八新台币，限时下杀一百零七新台币。",
              "kind": "product_claim",
              "fact_ids": ["PRICE", "PROMOTION"]
