        {
          "stage": "cta",
          "focus": "总结与购买引导",
          "sentences": [
            {
              "display_text": "这双鞋最值得关注的是足弓支撑、轻便快干和静音防滑。",
              "spoken_text": "这双鞋最值得关注的是足弓支撑、轻便快干和静音防滑。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
